<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from "vue";
import { useAuth } from "@papilio/auth";
import { item, request, query, type Page, type PaymentDestination, type SmsDevice, type SmsDeviceWrite, type SmsDeviceEnrollment, type SmsApprovalMode, type SmsOriginCapabilities, type SmsParserProfile, type SmsIdentityMode } from "@papilio/api";
import { faDate, faNumber } from "@papilio/ui";
import Modal from "@papilio/ui/Modal.vue";
import { useI18n } from "vue-i18n";
const props=defineProps<{capabilities?:SmsOriginCapabilities|null}>();
const {t}=useI18n();
const parserProfiles=ref<SmsParserProfile[]>([]),parserPage=ref(1),parserPages=ref(1),parserQ=ref(""),parserLoading=ref(false),parserError=ref(""),parserId=ref<number|null>(null),identity=ref<SmsIdentityMode>("bank_reference_required");
const originSupported=computed(()=>props.capabilities?.supported===true&&props.capabilities.enabled&&props.capabilities.capacity!==null);
const auth=useAuth(),base="/v1/admin/payments/sms-devices";
const rows=ref<SmsDevice[]>([]),page=ref(1),pages=ref(1),total=ref(0),state=ref<"loading"|"ready"|"error">("loading");
const deviceQ=ref(""),destinationCleared=ref(false),editedId=ref<number|null>(null),draftRevision=ref<number|undefined>();
const selected=ref<SmsDevice|null>(null),busy=ref(false),error=ref(""),notice=ref(""),editorOpen=ref(false),creating=ref(false);
const label=ref(""),senders=ref(""),active=ref(false),expiry=ref(""),mode=ref<SmsApprovalMode>("manual"),destination=ref<PaymentDestination|null>(null);
const destinations=ref<PaymentDestination[]>([]),destinationQ=ref(""),destinationPage=ref(1),destinationPages=ref(1),destinationState=ref<"idle"|"loading"|"ready"|"error">("idle"),destinationError=ref("");
const key=ref(""),keyDevice=ref<SmsDevice|null>(null),keyOpen=ref(false),showKey=ref(false),keyNotice=ref("");
const rotationOpen=ref(false),revocationOpen=ref(false);
const timezone=Intl.DateTimeFormat().resolvedOptions().timeZone;
const mayWrite=computed(()=>auth.can("payments",creating.value?"create":"update"));
let alive=true,listVersion=0,destinationVersion=0,parserVersion=0;
async function loadProfiles():Promise<void>{if(!originSupported.value)return;const version=++parserVersion;parserLoading.value=true;parserError.value="";try{const result=await request<Page<SmsParserProfile>>(`/v1/admin/payments/sms-origins/parser-profiles?${query({page:parserPage.value,q:parserQ.value})}`);if(!alive||version!==parserVersion)return;parserProfiles.value=result.data;parserPages.value=result.meta.pager?.total_pages??1;}catch(cause){if(alive&&version===parserVersion)parserError.value=fail(cause);}finally{if(alive&&version===parserVersion)parserLoading.value=false;}}
async function refreshDevice():Promise<void>{const id=selected.value?.id;if(!id||busy.value||!originSupported.value)return;busy.value=true;try{const row=await item<SmsDevice>(`${base}/${id}`);if(alive&&selected.value?.id===id)selected.value=row;}catch(cause){if(alive)error.value=fail(cause);}finally{if(alive)busy.value=false;}}
function fail(cause:unknown):string{return cause instanceof Error?cause.message:t("errors.request_failed");}
function localTime(value:string):string{const date=new Date(value);const local=new Date(date.getTime()-date.getTimezoneOffset()*60_000);return local.toISOString().slice(0,16);}
function reveal(value:SmsDeviceEnrollment):void{key.value=value.api_key;keyDevice.value=value.device;showKey.value=false;keyNotice.value="";keyOpen.value=true;}
function clearKey():void{key.value="";keyDevice.value=null;showKey.value=false;keyOpen.value=false;keyNotice.value="";}
async function load():Promise<void>{const version=++listVersion;state.value="loading";error.value="";try{const result=await request<Page<SmsDevice>>(`${base}?${query({page:page.value,q:deviceQ.value})}`);if(!alive||version!==listVersion)return;rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;total.value=result.meta.pager?.total_items??0;state.value="ready";}catch(cause){if(alive&&version===listVersion){error.value=fail(cause);state.value="error";}}}
async function loadDestinations():Promise<void>{const version=++destinationVersion;destinationState.value="loading";destinationError.value="";try{const result=await request<Page<PaymentDestination>>(`/v1/admin/payments/destinations?${query({q:destinationQ.value,page:destinationPage.value})}`);if(!alive||version!==destinationVersion)return;destinations.value=result.data;destinationPages.value=result.meta.pager?.total_pages??1;destinationState.value="ready";}catch(cause){if(alive&&version===destinationVersion){destinationError.value=fail(cause);destinationState.value="error";}}}
function choose(row:SmsDevice):void{if(busy.value)return;selected.value=row;notice.value="";}
function createDraft():void{if(busy.value||!auth.can("payments","create"))return;if(!creating.value){label.value="";senders.value="";expiry.value="";active.value=false;mode.value="manual";parserId.value=null;identity.value="bank_reference_required";destination.value=null;destinationCleared.value=false;editedId.value=null;draftRevision.value=undefined;creating.value=true;}editorOpen.value=true;error.value="";void loadDestinations();void loadProfiles();}
function editDraft():void{const row=selected.value;if(!row||busy.value)return;if(!creating.value&&editedId.value===row.id){editorOpen.value=true;return;}creating.value=false;editedId.value=row.id;draftRevision.value=row.revision;destinationCleared.value=false;label.value=row.label;senders.value=row.senders.join("\n");expiry.value=localTime(row.expires_at);active.value=row.is_active;parserId.value=row.parser_profile_id??null;identity.value=row.settlement_identity_mode??"bank_reference_required";mode.value=row.approval_mode==="unique_sms"?"unique_sms":"manual";destination.value=destinations.value.find(value=>value.destination_id===row.destination_id)??null;editorOpen.value=true;error.value="";void loadDestinations();void loadProfiles();}
function values():SmsDeviceWrite{const date=new Date(expiry.value);if(!expiry.value||!Number.isFinite(date.getTime()))throw new Error(t("paymentConfig.devices.invalidExpiry"));return {...(originSupported.value?{parser_profile_id:parserId.value,settlement_identity_mode:identity.value}:{}),label:label.value.trim(),senders:senders.value.split(/\r?\n/).map(value=>value.trim()).filter(Boolean),is_active:active.value,expires_at:date.toISOString(),approval_mode:mode.value,destination_id:destinationCleared.value?null:destination.value?.destination_id??(!creating.value?selected.value?.destination_id??null:null),...(!creating.value&&selected.value?{expected_revision:draftRevision.value}:{})};}
async function save():Promise<void>{if(busy.value||!mayWrite.value||!creating.value&&!selected.value)return;busy.value=true;error.value="";notice.value="";try{const data=values();if(creating.value){const result=await item<SmsDeviceEnrollment>(base,"POST",data);if(!alive)return;selected.value=result.device;reveal(result);}else{const row=selected.value!;const result=await item<SmsDevice>(`${base}/${row.id}`,"PUT",data);if(!alive)return;selected.value=result;}editorOpen.value=false;creating.value=false;editedId.value=null;notice.value=t("paymentConfig.devices.saved");await load();}catch(cause){if(alive)error.value=fail(cause);}finally{if(alive)busy.value=false;}}
async function revoke():Promise<void>{const row=selected.value;if(!row||busy.value||!auth.can("payments","update"))return;busy.value=true;error.value="";try{const result=await item<SmsDevice>(`${base}/${row.id}`,"PUT",{label:row.label,senders:row.senders,is_active:false,expires_at:row.expires_at,approval_mode:row.approval_mode,destination_id:row.destination_id,expected_revision:row.revision,...(Object.prototype.hasOwnProperty.call(row,"parser_profile_id")?{parser_profile_id:row.parser_profile_id}:{}),...(row.settlement_identity_mode?{settlement_identity_mode:row.settlement_identity_mode}:{})});if(!alive)return;selected.value=result;revocationOpen.value=false;notice.value=t("paymentConfig.devices.revokedNotice");await load();}catch(cause){if(alive)error.value=fail(cause);}finally{if(alive)busy.value=false;}}
async function rotate():Promise<void>{const row=selected.value;if(!row||busy.value||!auth.can("payments","update"))return;busy.value=true;error.value="";try{const result=await item<SmsDeviceEnrollment>(`${base}/${row.id}/rotate`,"POST",{expected_revision:row.revision});if(!alive)return;selected.value=result.device;rotationOpen.value=false;reveal(result);notice.value=t("paymentConfig.devices.rotatedNotice");await load();}catch(cause){if(alive)error.value=fail(cause);}finally{if(alive)busy.value=false;}}
async function copyKey():Promise<void>{try{await navigator.clipboard.writeText(key.value);keyNotice.value=t("paymentConfig.devices.copiedNotice");}catch{keyNotice.value=t("paymentConfig.devices.copyUnavailable");}}
onMounted(load);onUnmounted(()=>{alive=false;++listVersion;++destinationVersion;++parserVersion;clearKey();});
</script>
<template>
<section class="card card-pad"><div class="page-head"><div><p class="eyebrow">{{t('paymentConfig.devices.eyebrow')}}</p><h2>{{t('paymentConfig.devices.title')}}</h2><p class="subtitle">{{t('paymentConfig.devices.description')}}</p></div><button class="btn secondary" :disabled="busy||state==='loading'" @click="load">{{t('paymentConfig.devices.refresh')}}</button><button v-if="auth.can('payments','create')" class="btn" :disabled="busy" @click="createDraft">{{t('paymentConfig.devices.enroll')}}</button></div>
<p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message success" role="status">{{notice}}</p>
<form class="toolbar" @submit.prevent="page=1;load()"><label class="field"><span>{{t('paymentConfig.devices.searchName')}}</span><input v-model="deviceQ" maxlength="100" :disabled="busy"/></label><button class="btn secondary" :disabled="busy||state==='loading'">{{t('paymentConfig.devices.search')}}</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th>{{t('paymentConfig.devices.device')}}</th><th>{{t('paymentConfig.devices.approval')}}</th><th>{{t('paymentConfig.devices.expiry')}}</th><th>{{t('paymentConfig.devices.status')}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" tabindex="0" :class="{'selected-row':selected?.id===row.id}" @click="choose(row)" @keydown.enter="choose(row)"><td><strong>{{row.label}}</strong><small>{{t('paymentConfig.devices.deviceNumber',{id:faNumber(row.id),revision:faNumber(row.revision)})}}</small></td><td>{{row.approval_mode==='unique_sms'?t('paymentConfig.devices.uniqueApproval'):t('paymentConfig.devices.manualApproval')}}</td><td>{{faDate(row.expires_at)}}</td><td><span class="badge" :class="row.is_active?'success':'warning'">{{row.is_active?t('paymentConfig.devices.enabled'):t('paymentConfig.devices.revoked')}}</span></td></tr></tbody></table><p v-if="state==='loading'" class="empty">{{t('paymentConfig.devices.loading')}}</p><p v-else-if="state==='ready'&&!rows.length" class="empty">{{t('paymentConfig.devices.empty')}}</p></div><div class="pager"><button :disabled="page<=1||state==='loading'||busy" @click="page--;load()">‹</button><span>{{t('paymentConfig.devices.pageCount',{page:faNumber(page),pages:faNumber(pages),count:faNumber(total)})}}</span><button :disabled="page>=pages||state==='loading'||busy" @click="page++;load()">›</button></div>
<section v-if="selected" class="record-detail"><h3>{{selected.label}}</h3><p>{{t('paymentConfig.devices.revisionDestination',{revision:faNumber(selected.revision),destination:selected.destination_id===null?t('paymentConfig.devices.unassigned'):faNumber(selected.destination_id)})}}</p><p>{{t('paymentConfig.devices.allowedSenders',{senders:selected.senders.join(', ')})}}</p><code>/v1/webhooks/sms-devices/{{selected.id}}</code><div class="inline-actions"><button v-if="auth.can('payments','update')" class="btn secondary" :disabled="busy" @click="editDraft">{{t('paymentConfig.devices.edit')}}</button><button v-if="auth.can('payments','update')" class="btn secondary" :disabled="busy" @click="rotationOpen=true">{{t('paymentConfig.devices.rotate')}}</button><button v-if="auth.can('payments','update')&&selected.is_active" class="btn danger" :disabled="busy" @click="revocationOpen=true">{{t('paymentConfig.devices.revoke')}}</button></div></section>
</section>
<Modal v-model="editorOpen" :title="creating?t('paymentConfig.devices.enrollTitle'):t('paymentConfig.devices.editTitle')" :busy="busy" wide><p v-if="error" class="message error" role="alert">{{error}}</p><form class="form-grid" @submit.prevent="save"><label class="field"><span>{{t('paymentConfig.devices.name')}}</span><input v-model="label" minlength="2" maxlength="100" required :disabled="busy"/></label><label class="field"><span>{{t('paymentConfig.devices.senderIds')}}</span><textarea v-model="senders" required :disabled="busy"/><small>{{t('paymentConfig.devices.signedSenderHint')}}</small></label><label class="field"><span>{{t('paymentConfig.devices.expiryTimezone',{timezone})}}</span><input v-model="expiry" type="datetime-local" required :disabled="busy"/></label><label class="check-row"><input v-model="active" type="checkbox" :disabled="busy"/>{{t('paymentConfig.devices.deviceEnabled')}}</label><label class="field"><span>{{t('paymentConfig.devices.approvalPolicy')}}</span><select v-model="mode" :disabled="busy"><option value="manual">{{t('paymentConfig.devices.manualPolicy')}}</option><option value="unique_sms">{{t('paymentConfig.devices.uniquePolicy')}}</option></select></label><section v-if="originSupported" class="form-grid"><label class="field"><span>{{t('paymentConfig.devices.identityPolicy')}}</span><select v-model="identity" :disabled="busy"><option v-for="value in capabilities?.identity_modes" :key="value" :value="value">{{value==='bank_reference_required'?t('paymentConfig.devices.bankReference'):t('paymentConfig.devices.trustedFingerprint')}}</option></select></label><p class="hint-box">{{t('paymentConfig.devices.trustedOriginHint')}}</p><p>{{t('paymentConfig.devices.selectedProfile',{profile:parserId===null?t('paymentConfig.devices.noneLegacy'):t('paymentConfig.devices.profileId',{id:parserId})})}}</p><button v-if="parserId!==null" type="button" class="btn small secondary" :disabled="busy" @click="parserId=null">{{t('paymentConfig.devices.clearProfile')}}</button><div class="toolbar"><label class="field"><span>{{t('paymentConfig.devices.findProfile')}}</span><input v-model="parserQ" :disabled="busy" @keydown.enter.prevent="parserPage=1;loadProfiles()"/></label><button type="button" class="btn secondary" :disabled="busy||parserLoading" @click="parserPage=1;loadProfiles()">{{t('paymentConfig.devices.searchProfiles')}}</button></div><p v-if="parserError" class="message error" role="alert">{{parserError}}</p><p v-if="parserLoading">{{t('paymentConfig.devices.loadingProfiles')}}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>{{t('paymentConfig.devices.profile')}}</th><th>{{t('paymentConfig.devices.status')}}</th><th></th></tr></thead><tbody><tr v-for="row in parserProfiles" :key="row.id"><td>{{row.title}}</td><td>{{row.is_active?t('paymentConfig.devices.enabled'):t('paymentConfig.devices.disabled')}}</td><td><button type="button" class="btn small secondary" :disabled="busy||!row.is_active" @click="parserId=row.id">{{parserId===row.id?t('paymentConfig.devices.selected'):t('paymentConfig.devices.select')}}</button></td></tr></tbody></table></div><div class="pager"><button type="button" :disabled="busy||parserLoading||parserPage<=1" @click="parserPage--;loadProfiles()">‹</button><span>{{faNumber(parserPage)}} / {{faNumber(parserPages)}}</span><button type="button" :disabled="busy||parserLoading||parserPage>=parserPages" @click="parserPage++;loadProfiles()">›</button></div><button v-if="!creating" type="button" class="btn secondary" :disabled="busy" @click="refreshDevice">{{t('paymentConfig.devices.refreshDraft')}}</button></section><div v-if="!creating&&selected&&editedId===selected.id&&draftRevision!==selected.revision" class="hint-box"><p>{{t('paymentConfig.devices.staleRevision')}}</p><button type="button" class="btn secondary" :disabled="busy" @click="draftRevision=selected.revision">{{t('paymentConfig.devices.useRevision')}}</button></div><p class="hint-box">{{t('paymentConfig.devices.automaticHint')}}</p><p v-if="destination">{{t('paymentConfig.devices.selectedDestination',{title:destination.title,bank:destination.bank_name})}}<button type="button" class="btn small secondary" :disabled="busy" @click="destination=null;destinationCleared=true">{{t('paymentConfig.devices.clearSelection')}}</button></p><p v-else-if="!creating&&selected?.destination_id&&!destinationCleared">{{t('paymentConfig.devices.currentDestination',{id:faNumber(selected.destination_id)})}}</p><div class="toolbar"><label class="field"><span>{{t('paymentConfig.devices.findDestination')}}</span><input v-model="destinationQ" :disabled="busy" @keydown.enter.prevent="destinationPage=1;loadDestinations()"/></label><button type="button" class="btn secondary" :disabled="busy||destinationState==='loading'" @click="destinationPage=1;loadDestinations()">{{t('paymentConfig.devices.searchDestinations')}}</button></div><p v-if="destinationError" class="message error">{{destinationError}}</p><p v-if="destinationState==='loading'">{{t('paymentConfig.devices.loadingDestinations')}}</p><table class="data-table"><thead><tr><th>{{t('paymentConfig.devices.destination')}}</th><th>{{t('paymentConfig.destination.bank')}}</th><th>{{t('paymentConfig.devices.status')}}</th><th></th></tr></thead><tbody><tr v-for="row in destinations" :key="row.destination_id"><td>{{row.title}}</td><td>{{row.bank_name}}</td><td>{{row.is_active?t('paymentConfig.devices.enabled'):t('paymentConfig.inactive')}}</td><td><button type="button" class="btn small secondary" :disabled="busy" @click="destination=row;destinationCleared=false">{{destination?.destination_id===row.destination_id?t('paymentConfig.devices.selected'):t('paymentConfig.devices.select')}}</button></td></tr></tbody></table><p v-if="destinationState==='ready'&&!destinations.length">{{t('paymentConfig.devices.noDestinations')}}</p><div class="pager"><button type="button" :disabled="destinationPage<=1||destinationState==='loading'||busy" @click="destinationPage--;loadDestinations()">‹</button><span>{{faNumber(destinationPage)}} / {{faNumber(destinationPages)}}</span><button type="button" :disabled="destinationPage>=destinationPages||destinationState==='loading'||busy" @click="destinationPage++;loadDestinations()">›</button></div><button class="btn" :disabled="busy||!mayWrite">{{creating?t('paymentConfig.devices.enrollReveal'):t('paymentConfig.devices.saveDevice')}}</button></form></Modal>
<Modal v-model="rotationOpen" :title="t('paymentConfig.devices.rotateTitle')" :busy="busy"><p v-if="error" class="message error" role="alert">{{error}}</p><p>{{t('paymentConfig.devices.rotateHint')}}</p><button class="btn" :disabled="busy" @click="rotate">{{t('paymentConfig.devices.rotateReveal')}}</button></Modal>
<Modal v-model="revocationOpen" :title="t('paymentConfig.devices.revokeTitle')" :busy="busy"><p v-if="error" class="message error" role="alert">{{error}}</p><p>{{t('paymentConfig.devices.revokeHint')}}</p><button class="btn danger" :disabled="busy" @click="revoke">{{t('paymentConfig.devices.revoke')}}</button></Modal>
<Modal v-model="keyOpen" :title="t('paymentConfig.devices.keyTitle')" @update:model-value="value=>{if(!value)clearKey();}"><p>{{t('paymentConfig.devices.keyHint')}}</p><p v-if="keyDevice">{{t('paymentConfig.devices.keyDeviceNumber',{id:faNumber(keyDevice.id),label:keyDevice.label})}}</p><label class="field"><span>{{t('paymentConfig.devices.privateKey')}}</span><input :type="showKey?'text':'password'" :value="key" readonly autocomplete="off"/></label><div class="inline-actions"><button class="btn secondary" @click="showKey=!showKey">{{showKey?t('paymentConfig.devices.hideKey'):t('paymentConfig.devices.revealKey')}}</button><button class="btn" @click="copyKey">{{t('paymentConfig.devices.copyKey')}}</button></div><p v-if="keyNotice" role="status">{{keyNotice}}</p><p>{{t('paymentConfig.devices.webhookHint')}}</p><button class="btn secondary" @click="clearKey">{{t('paymentConfig.devices.saveKey')}}</button></Modal>
</template>
<style scoped>small{display:block;color:var(--muted)}.record-detail{margin-top:16px;padding-top:16px;border-top:1px solid var(--line)}code{overflow-wrap:anywhere}</style>
